import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

relu_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void relu_kernel(const float* input, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        output[idx] = fmaxf(0.0f, input[idx]);
    }
}

torch::Tensor relu_forward_cuda(torch::Tensor input) {
    auto output = torch::zeros_like(input);
    int num_elements = input.numel();

    const int threads_per_block = 256;
    int num_blocks = (num_elements + threads_per_block - 1) / threads_per_block;

    relu_kernel<<<num_blocks, threads_per_block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}
"""

relu_cpp_source = "torch::Tensor relu_forward_cuda(torch::Tensor input);"

relu_cuda = load_inline(
    name="relu_cuda",
    cpp_sources=relu_cpp_source,
    cuda_sources=relu_source,
    functions=["relu_forward_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.relu_cuda = relu_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.relu_cuda.relu_forward_cuda(x)
